'use strict';
const SITE_URL='https://clynera.vercel.com';
const chapters=[['overview','A better practice'],['patients','The patient journey'],['clinical','Space for better care'],['team','A team in sync'],['revenue','Every rupee, accounted for'],['explore','Take a closer look']];
const main=document.querySelector('#main');
let current=0,screen='overview',patientStep=0,selectedSlot='',clinicalTab='notes',teamTab='roster',revenueTab='collections',toastTimer;
const list=(items)=>`<ul class="feature-list">${items.map((x,i)=>`<li><span class="num">0${i+1}</span><div><strong>${x[0]}</strong><p>${x[1]}</p></div></li>`).join('')}</ul>`;
const tabs=(items,type,active)=>`<div class="tabs" role="group" aria-label="${type} preview">${items.map(([id,label])=>`<button data-${type}="${id}" class="${active===id?'active':''}" aria-pressed="${active===id}">${label}</button>`).join('')}</div>`;
const phone=()=>`<div class="phone"><div class="phone-inner"><div class="island"></div><div class="phone-top">Appointments <span class="avatar">A</span></div><div class="phone-date">◷ &nbsp; October 23, 2026</div><h4>Today's schedule</h4><div class="phone-therapist">Aisha Rahman <span style="float:right">⌄</span></div><div class="phone-slot">09:30 AM · Available</div><div class="phone-slot booked"><b>Mira Thomas</b>Psychotherapy · Confirmed<br><br>10:00 AM &nbsp; 60 mins</div><div class="phone-slot">11:00 AM · Available</div><div class="phone-nav"><span>⌂ Home</span><span>◷ Schedule</span><span>▤ Clients</span></div></div></div>`;
const dashboard=()=>`<div class="dash-heading">${screen==='overview'?'Dashboard':'Appointments'} <span class="avatar">A</span></div>${screen==='overview'?`<div class="dash-banner"><small>OPERATIONS OVERVIEW</small><h3>Clinical performance is steady.<br>You're ready for a day of care.</h3><p>Registrations, revenue, sessions and your team.<br>One connected view.</p><div class="metrics"><div><small>ACTIVE CLIENTS</small><b>43</b></div><div><small>TODAY'S SESSIONS</small><b>5</b></div><div><small>THERAPISTS</small><b>5</b></div></div></div><div class="upcoming"><span class="avatar">AR</span><div><b>Aisha Rahman</b>Next consultation · 10:00 AM</div><em>On schedule</em></div>`:`<div class="upcoming" style="margin-bottom:12px">Today &nbsp; / &nbsp; October 23, 2026 <em>Live grid</em></div><div class="schedule-grid"><b>Therapist</b><b>09:00</b><b>10:00</b><b>11:00</b><b>Aisha Rahman</b><span class="slot">Available</span><span class="slot">Mira T.</span><span>—</span><b>John Mathew</b><span class="slot">Session</span><span>—</span><span class="slot">Available</span><b>Arjun Rao</b><span>—</span><span class="slot">Session</span><span>—</span></div>`}`;
function overview(){return `<div class="page-grid"><section><p class="eyebrow">ONE CONNECTED CLINIC</p><h1 class="hero-title">Less admin.<br>More <span class="accent serif">care.</span></h1><p class="lead">The intelligent operating system for modern clinics & therapy practices. A little less complexity. A lot more connection.</p><div class="actions"><button class="pill dark" data-page="1">Open the experience <span>↗</span></button><button class="pill light" data-page="5">View brochure <span>↓</span></button></div><div class="hero-meta"><div><strong>For your patients</strong>A smoother journey</div><div><strong>For your team</strong>A clearer working day</div></div></section><div class="product-stage"><div class="halo"></div><div class="orbit"></div><div class="device-controls" role="group" aria-label="Desktop screen"><button data-screen="overview" class="${screen==='overview'?'active':''}" aria-pressed="${screen==='overview'}">Overview</button><button data-screen="schedule" class="${screen==='schedule'?'active':''}" aria-pressed="${screen==='schedule'}">Appointments</button></div><div class="monitor"><div class="screen"><aside class="sidebar"><div class="mini-brand">Clynera</div><span class="selected">⌂ &nbsp; Dashboard</span><small>FRONT DESK & INTAKE</small><span>＋ &nbsp; Client registration</span><span>☷ &nbsp; Client directory</span><small>CLINICAL OPERATIONS</small><span>▦ &nbsp; Appointments</span><span>◷ &nbsp; Practitioner calendar</span><span>▤ &nbsp; Therapy sessions</span></aside><div class="dashboard">${dashboard()}</div></div></div>${phone()}<div class="floating-note"><span class="check">✓</span><div><strong>Everything, working together.</strong>From the first booking to the final bill.</div></div><span class="demo-label">ILLUSTRATIVE UI · FICTIONAL NAMES & SAMPLE DATA</span></div></div>`}
function patientPreview(){return `<div class="interaction-title"><div><h3>A change of plans. Handled.</h3><p>Try the patient rescheduling experience.</p></div><span class="tag">INTERACTIVE DEMO</span></div><div class="steps">${[0,1,2].map(i=>`<span class="${patientStep>=i?'done':''}"></span>`).join('')}</div>${patientStep===0?`<div class="chat-preview"><div class="chat-bubble"><b>CLYNERA · APPOINTMENT UPDATE</b>Hi Mira, Aisha Rahman is running 20 minutes behind schedule. Your updated appointment is at 10:20 AM.<small>WhatsApp message preview</small></div></div><button class="pill dark" data-patient="1">Preview reschedule options <span>→</span></button>`:patientStep===1?`<div class="chat-preview"><div class="chat-bubble"><b>CHOOSE WHAT WORKS FOR YOU</b>Need a different time? Pick an available slot with Aisha Rahman.<div class="slot-choices"><button data-slot="Today, 11:30 AM">Today<br><strong>11:30 AM</strong></button><button data-slot="Today, 3:00 PM">Today<br><strong>3:00 PM</strong></button><button data-slot="Tomorrow, 10:00 AM">Tomorrow<br><strong>10:00 AM</strong></button></div></div></div><button class="text-button" data-patient="0" style="margin-top:22px">← Back to delay alert</button>`:`<div class="success"><span class="success-icon">✓</span><h3>A new time. A calmer day.</h3><p>Your sample appointment with <strong>Aisha Rahman</strong><br>is set for <strong>${selectedSlot}</strong>.</p><button class="pill light" data-patient="0">Replay experience ↺</button></div>`}<p class="simulation-label">Illustrative demo only. No message is sent and no appointment is booked.</p>`}
function patients(){return `<div class="page-grid"><section><p class="eyebrow">02 / THE PATIENT JOURNEY</p><h1 class="section-title">Care begins<br><span class="accent serif">before the visit.</span></h1><p class="lead">Help patients feel informed, reassured and in control—even when the day changes.</p>${list([['A familiar face before booking','Clinician video and audio introductions help patients get to know their practitioner.'],['A heads-up, right on WhatsApp','One-click delay alerts keep upcoming patients informed.'],['A new appointment in a few taps','Secure self-service links offer alternative slots, with team resolution workflows when needed.']])}</section><section class="interaction" id="patient-preview" aria-label="Patient rescheduling demo">${patientPreview()}</section></div>`}
function clinicalPreview(){return `<div class="workspace-top"><div><h3>Clinical workspace</h3><small>Aisha Rahman · Therapist view</small></div><span class="tag">IN SESSION</span></div><div class="workspace-body"><div class="patient-line"><span class="avatar">MT</span><div><strong>Mira Thomas</strong><p>Psychotherapy · Follow-up</p></div><div class="timer">24:38<small>ILLUSTRATIVE SESSION TIMER</small></div></div>${tabs([['notes','Session notes'],['prescription','E-prescription'],['queue','Live queue']],'clinical',clinicalTab)}${clinicalTab==='notes'?`<div class="note-area"><small>SESSION NOTES</small><p>Discussed progress since the previous visit.<br>Reviewed goals and planned the next follow-up.</p></div><div class="saved">✓ Auto-save preview</div>`:clinicalTab==='prescription'?`<div class="note-area"><small>SMART PRESCRIPTION PRESETS</small><div class="rx-row"><span>Dosage</span><span>Frequency</span><span>Timing</span></div><div class="rx-row"><b>Preset dose</b><span>OD / BD / TID</span><span>Before / after food</span></div><p>Secure QR-linked prescription delivery to the patient's WhatsApp.</p></div><div class="saved">Illustrative workflow · No medical advice</div>`:`<div class="note-area"><small>LIVE OPD QUEUE</small><div class="ledger"><span>01 · Mira Thomas</span><b>In session</b></div><div class="ledger"><span>02 · Arjun Rao</span><b>Waiting · 6 min</b></div><p>Queue timestamps and a calling chime help reception coordinate each visit.</p></div><div class="saved">Fictional queue · Sample waiting time</div>`}</div>`}
function clinical(){return `<div class="page-grid"><section><p class="eyebrow">03 / CLINICAL CLARITY</p><h1 class="section-title">Present with<br>your patients.<br><span class="accent serif">Not your paperwork.</span></h1><p class="lead">Keep the consultation flowing with the tools you need, together in one workspace.</p><div class="details-stack"><details open><summary>A focused clinical workspace</summary><p>Session countdowns and background auto-saving notes support a more organised consultation.</p></details><details><summary>Smart e-prescriptions</summary><p>Dosage, frequency and food-timing presets simplify prescribing. Secure QR links make digital prescriptions easy to access.</p></details><details><summary>A calmer waiting room</summary><p>Live OPD queues, timestamps and an audio calling chime keep patients moving through the clinic.</p></details></div></section><section class="workspace" id="clinical-preview" aria-label="Clinical workspace preview">${clinicalPreview()}</section></div>`}
function teamPreview(){return `<div class="interaction-title"><div><h3>Your team, at a glance.</h3><p>One connected view of the working week.</p></div><span class="tag">TEAM OPERATIONS</span></div>${tabs([['roster','Shifts'],['attendance','Attendance'],['payroll','Payroll']],'team',teamTab)}${teamTab==='roster'?`<div class="roster"><span></span><span class="day">MON</span><span class="day">TUE</span><span class="day">WED</span><span>Aisha Rahman</span><span class="shift">Morning</span><span class="shift evening">Evening</span><span class="shift">Morning</span><span>John Mathew</span><span class="shift evening">Evening</span><span class="shift">Morning</span><span class="shift off">Day off</span><span>Arjun Rao</span><span class="shift">Morning</span><span class="shift off">Day off</span><span class="shift evening">On-call</span></div><div class="summary-box">Visual weekly rostering with drag-and-drop planning and colleague shift-swap workflows.</div>`:teamTab==='attendance'?`<div class="ledger"><span>Morning grace period<small>Configurable attendance rules</small></span><b>15 minutes</b></div><div class="ledger"><span>Late-mark policy<small>Sample rule · configurable</small></span><b>3 lates = 0.5 day</b></div><div class="ledger"><span>Break intervals</span><b>Tracked</b></div><div class="summary-box">ZKTeco / eSSL biometric attendance connects to policy rules and regularization approvals.</div>`:`<div class="ledger"><span>Salary components</span><b>Basic · HRA · DA</b></div><div class="ledger"><span>Deductions & taxes</span><b>PF · ESI · PT · TDS</b></div><div class="ledger"><span>Clinician commissions</span><b>Fee per session</b></div><div class="summary-box">Bring salary and session commissions together, with bank NEFT exports for payroll processing.</div>`}<p class="simulation-label">Illustrative preview with fictional team members and sample policy settings.</p>`}
function team(){return `<div class="page-grid"><section><p class="eyebrow">04 / PEOPLE & OPERATIONS</p><h1 class="section-title">A team in sync.<br>A practice<br><span class="accent serif">in balance.</span></h1><p class="lead">Connect the roster, attendance and payroll. Give your people a clearer working day.</p>${list([['Plan the week visually','Morning, evening and on-call shifts in a weekly rostering matrix.'],['Make attendance rules work for you','Configurable grace periods, late penalties, break tracking and approval workflows.'],['Bring payroll together','Indian salary components, statutory deductions and clinician session commissions.']])}</section><section class="interaction" id="team-preview" aria-label="Team operations preview">${teamPreview()}</section></div>`}
function revenuePreview(){return `<div class="interaction-title"><div><h3>Day book</h3><p>Illustrative end-of-shift summary</p></div><span class="tag">RECEPTION VIEW</span></div>${tabs([['collections','Collections'],['reconciliation','Reconciliation']],'revenue',revenueTab)}${revenueTab==='collections'?`<div class="statement"><small>TODAY'S COLLECTIONS · SAMPLE DATA</small>₹24,000<span class="accent">.</span></div><div class="money-bars"><span></span><span></span><span></span></div><div class="legend"><span>Cash · 35%</span><span>UPI · 45%</span><span>Card · 20%</span></div><div class="alert"><strong>Revenue leakage check</strong><br>15-minute sweeps flag completed sessions awaiting billing, helping your team follow up.</div>`:`<div class="ledger"><span>Opening cash</span><b>₹5,000</b></div><div class="ledger"><span>Cash collections</span><b>+ ₹8,400</b></div><div class="ledger"><span>Cash expenses</span><b>− ₹1,200</b></div><div class="ledger total"><strong>Expected closing cash</strong><strong>₹12,200</strong></div><div class="summary-box">Opening cash + cash collections − cash expenses = expected closing cash.</div>`}<p class="simulation-label">Example figures for product illustration. This preview does not access financial records.</p>`}
function revenue(){return `<div class="page-grid"><section><p class="eyebrow">05 / FINANCIAL VISIBILITY</p><h1 class="section-title">Every visit counts.<br><span class="accent serif">Every rupee, too.</span></h1><p class="lead">Bring billing, collections and shift-end reconciliation into the same picture.</p>${list([['Catch the billing gaps','Automated checks flag completed sessions that have not yet been billed.'],['Make payment flexible','Combine Cash, UPI and Card on a single invoice. Share Razorpay payment links via WhatsApp.'],['Close the day with clarity','Track opening cash, collections and expenses in a balanced shift-end register.']])}</section><section class="interaction" id="revenue-preview" aria-label="Financial overview preview">${revenuePreview()}</section></div>`}
const galleryItems={outside:['brochure-outside.png','Tri-fold brochure — exterior'],inside:['brochure-inside.png','Tri-fold brochure — interior'],care:['poster-care.png','Less admin. More care.'],scheduling:['poster-scheduling.png','Plans change. Care continues.']};
function explore(){return `<section><p class="eyebrow">06 / THE BIGGER PICTURE</p><div class="collection-head"><h1 class="section-title">One connected clinic.<br><span class="accent serif">Every step of care.</span></h1><p class="lead">Take a closer look at the Clynera brochure and campaign. Open an artwork to explore or download it.</p></div><div class="art-grid"><button class="art-card" data-art="outside"><div class="art-thumb"><img src="assets/brochure-outside.png" alt="Clynera tri-fold brochure exterior" loading="lazy"></div><div class="art-caption"><span>The Clynera brochure<small>EXTERIOR · 3 PANELS</small></span><span>↗</span></div></button><button class="art-card" data-art="care"><div class="art-thumb"><img src="assets/poster-care.png" alt="Less admin. More care. campaign poster" loading="lazy"></div><div class="art-caption"><span>More care.<small>CAMPAIGN · 01</small></span><span>↗</span></div></button><button class="art-card" data-art="scheduling"><div class="art-thumb"><img src="assets/poster-scheduling.png" alt="Plans change. Care continues. campaign poster" loading="lazy"></div><div class="art-caption"><span>Care continues.<small>CAMPAIGN · 02</small></span><span>↗</span></div></button></div><div class="finish-line"><div><h3>Your next chapter starts here.</h3><p>Built for modern clinics & therapy practices.</p></div><div class="actions"><button class="pill light" data-art="inside">Inside the brochure ↗</button><a class="pill dark" href="${SITE_URL}" target="_blank" rel="noopener noreferrer">Visit Clynera <span>↗</span></a></div></div><details style="margin-top:25px" class="details-stack"><summary>Explore the full feature set</summary><div class="feature-directory">${['Clinician video & audio introductions','WhatsApp delay alerts','Patient self-service rescheduling','Peer clinician & admin resolution workflows','Live OPD queue & calling chime','Clinical notes & session timers','Smart e-prescriptions','Revenue leakage alerts','Day book & cash reconciliation','Split Cash / UPI / Card billing','Direct hardware biometrics','Attendance policy engine','Visual shift rostering','Indian payroll & session commissions','WhatsApp reminders & patient CRM'].map(x=>`<div>${x}</div>`).join('')}</div></details></section>`}
const renderers=[overview,patients,clinical,team,revenue,explore];
function go(index,updateHash=true,focus=false){if(index<0||index>=chapters.length)return;const reverse=index<current;current=index;main.innerHTML=`<article class="page ${reverse?'reverse':''}">${renderers[index]()}</article>`;document.querySelector('#page-number').textContent=String(index+1).padStart(2,'0');document.querySelector('#page-name').textContent=chapters[index][1];document.querySelector('#progress').style.width=`${(index+1)/chapters.length*100}%`;document.querySelector('#prev').disabled=index===0;document.querySelector('#next').disabled=index===chapters.length-1;document.querySelectorAll('.dots button').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-current',i===index?'step':'false')});if(updateHash)history.replaceState(null,'',`#${chapters[index][0]}`);window.scrollTo({top:0,behavior:'instant'});if(focus)main.focus({preventScroll:true})}
function toast(message){const el=document.querySelector('#toast');clearTimeout(toastTimer);el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function updatePreview(id,fn,selector){document.querySelector(id).innerHTML=fn();if(selector)document.querySelector(selector)?.focus({preventScroll:true})}
document.querySelector('.dots').innerHTML=chapters.map(([id,label],i)=>`<button data-page="${i}" aria-label="Chapter ${i+1}: ${label}"></button>`).join('');
document.querySelector('#chapter-links').innerHTML=chapters.map(([id,label],i)=>`<button class="chapter-link" data-page="${i}"><span>0${i+1}</span><span>${label}</span><span>↗</span></button>`).join('');
document.querySelector('#contents-button').addEventListener('click',()=>document.querySelector('#contents').showModal());
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}})});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page!==undefined){document.querySelector('#contents').close();go(Number(b.dataset.page),true,true)}if(b.dataset.screen){screen=b.dataset.screen;go(current);document.querySelector(`[data-screen="${screen}"]`).focus({preventScroll:true})}if(b.dataset.patient!==undefined){patientStep=Number(b.dataset.patient);updatePreview('#patient-preview',patientPreview,patientStep===1?'[data-slot]':'[data-patient]')}if(b.dataset.slot){selectedSlot=b.dataset.slot;patientStep=2;updatePreview('#patient-preview',patientPreview,'[data-patient]')}if(b.dataset.clinical){clinicalTab=b.dataset.clinical;updatePreview('#clinical-preview',clinicalPreview,`[data-clinical="${clinicalTab}"]`)}if(b.dataset.team){teamTab=b.dataset.team;updatePreview('#team-preview',teamPreview,`[data-team="${teamTab}"]`)}if(b.dataset.revenue){revenueTab=b.dataset.revenue;updatePreview('#revenue-preview',revenuePreview,`[data-revenue="${revenueTab}"]`)}if(b.dataset.art){const [file,title]=galleryItems[b.dataset.art];document.querySelector('#gallery-title').textContent=title;document.querySelector('#gallery-image').src=`assets/${file}`;document.querySelector('#gallery-image').alt=title;document.querySelector('#gallery-download').href=`assets/${file}`;document.querySelector('#gallery').showModal()}});
document.querySelector('#prev').onclick=()=>go(current-1,true,true);document.querySelector('#next').onclick=()=>go(current+1,true,true);
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();go(current+1,true,true)}if(e.key==='ArrowLeft'){e.preventDefault();go(current-1,true,true)}});
let touchStart;main.addEventListener('touchstart',e=>{if(e.target.closest('button,a,details')){touchStart=null;return}touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});main.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*2)go(current+(dx<0?1:-1),true,true);touchStart=null},{passive:true});
document.querySelector('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Fullscreen is not supported in this browser.')}catch{toast('Fullscreen is unavailable. You can still explore every chapter.')}};
document.addEventListener('fullscreenchange',()=>document.querySelector('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen presentation':'Enter fullscreen presentation'));
function route(){const index=chapters.findIndex(([id])=>id===location.hash.slice(1));go(index<0?0:index,false)}window.addEventListener('hashchange',route);route();
